-- Decima e ULTIMA infornata dal libro "Fiori e Piante da
-- Appartamento" (#120 espansione catalogo) — 4 nuove specie:
-- Thunbergia, Triplochlamys, Vriesea, Zantedeschia.
--
-- Con questo blocco si conclude l'elaborazione delle 194 foto del
-- libro (l'ultima pagina fotografata era la tabella riassuntiva delle
-- fioriture e la legenda dei simboli, non nuove specie).
--
-- Zantedeschia (calla): nessun simbolo "!" nel libro, ma segnalata la
-- tossicità (ossalato di calcio) come fatto botanico generale
-- ampiamente documentato, non specificamente fonte-flaggato.
--
-- Triplochlamys: nota tassonomica esplicitata dalla fonte stessa — la
-- specie coltivata era storicamente inserita nel genere Pavonia.
--
-- giorni_germinazione/giorni_trapianto/giorni_raccolta e npk lasciati
-- null per tutte le 4 specie: il libro non fornisce questi dati.

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Thunbergia$t$, $t$Thunbergia alata$t$, $t$Acanthaceae$t$, $t$Thunbergia, un genere indigeno dell'America centrale e meridionale, dell'Asia e del Madagascar, comprende circa 200 specie tra le quali è particolarmente conosciuta la T. alata. Questa specie, dal caratteristico 'occhio nero', viene in genere coltivata come pianta annuale attorcigliata a un tutore o a un graticcio. Le specie di Thunbergia sono piante erbacee o arborescenti, annuali o perenni, con foglie opposte e splendidi fiori di colore blu, giallo, arancione o bianco, in genere solitari, con una grande corolla imbutiforme formata da cinque petali. T. alata è una pianta rampicante perenne, coltivata come annuale. Ha foglie triangolari, ovali, dentellate, fusti volubili e fiori di un arancione acceso con al centro un 'occhio nero'; 'Alba' ha fiori bianchi con occhio nero. T. fragrans è una pianta perenne, rampicante, con fusti legnosi, e lunghe foglie lucenti, triangolari, ovali, picciolate. Ha fiori semplici, di colore bianco, profumati.$t$, $j${"luce": "Pieno sole, calda", "acqua": "Regolare", "terreno": "Non specificato dalla fonte; terriccio universale"}$j$::jsonb, ARRAY[$t$entrambe le specie richiedono una posizione soleggiata e calda, e non vanno esposte alle correnti d'aria$t$, $t$in genere T. alata muore dopo la fioritura; T. fragrans può essere invece conservata sul davanzale della finestra e, se necessario, rinvasata$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "regolare", "estate": "regolare", "autunno": "diradare", "inverno": "sospesa (T. alata muore dopo la fioritura)"}, "concimazione": {"primavera": "una volta alla settimana", "estate": "una volta alla settimana", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Acanthaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera"], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$thunbergia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Triplochlamys$t$, $t$Triplochlamys multiflora$t$, $t$Malvaceae$t$, $t$Triplochlamys, un genere diffuso nelle regioni tropicali dell'America meridionale, è formato da 5 specie, di cui una sola, la T. multiflora (in passato inserita nel genere Pavonia), viene coltivata. Da un processo di selezione sono state ottenute piante resistenti che fioriscono tutto l'anno. Si tratta di un arbusto perenne con lunghe foglie sparse, picciolate, a margini lisci o dentellati, con stipole alla base dei piccioli. I fiori sono rosso-rosacei o porporini con un anello di cinque o più brattee lineari. T. multiflora (sin. Pavonia multiflora, P. rosea) ha foglie leggermente pelose e dentellate, di colore verde chiaro o scuro. I fiori rosso-porporini sono solitari, crescono all'ascella delle foglie più alte e hanno il calice rosso acceso.$t$, $j${"luce": "Luminosa, ma non esposta ai raggi diretti del sole", "acqua": "Regolare, terreno sempre umido; immergere la pianta nell'acqua quando le foglie appassiscono", "terreno": "Normale terreno per vasi, ricco di humus"}$j$::jsonb, ARRAY[$t$nota tassonomica: in passato la specie coltivata era inserita nel genere Pavonia (sin. Pavonia multiflora, P. rosea)$t$, $t$in inverno la pianta non tollera una temperatura inferiore ai 12°C$t$, $t$per conservare a lungo la sua bellezza necessita spesso di un periodo di riposo a una temperatura un po' più bassa e con poca acqua$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "regolare, terreno sempre umido", "estate": "regolare, terreno sempre umido", "autunno": "regolare, terreno sempre umido", "inverno": "poca acqua, riposo a temperatura non inferiore a 12°C"}, "concimazione": {"primavera": "una volta alla settimana (dalla primavera all'autunno)", "estate": "una volta alla settimana (dalla primavera all'autunno)", "autunno": "una volta alla settimana (dalla primavera all'autunno)", "inverno": "sospesa"}, "potatura": {"primavera": "potare a 20-30cm dal suolo in primavera", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Malvaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 50, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 4, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.85}$j$::jsonb, $t$perenne$t$, $t$triplochlamys$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Vriesea$t$, $t$Vriesea splendens$t$, $t$Bromeliaceae$t$, $t$Molte delle circa 250 specie, per lo più epifite, del genere Vriesea, originario dell'America centrale e meridionale, vengono coltivate. Vi sono anche molti ibridi disponibili. Queste piante hanno splendide foglie allungate, esili, a margini lisci, spesso striate, disposte in grandi rosette imbutiformi e una bellissima spiga colorata. Dopo la fioritura la rosetta avvizzisce per lungo tempo e nuove piante possono essere coltivate dai giovani getti. V. carinata ha larghe foglie linguiformi, di colore verde chiaro, disposte in una rosetta cilindrica e un fusto rosso, non ramificato, lungo 15-30cm che sorregge fiori gialli dalla punta verde, con brattee rosse alla base e gialle in punta, screziate di verde. V. fenestralis ha foglie disposte a rosetta, di colore verde chiaro, con striature di un verde più scuro e macchie color porpora sulla pagina inferiore; il fusto, lungo 30-75cm, non è ramificato, e sorregge fiori bianco-giallastri, con brattee verdi. V. hieroglyphica ha grandi rosette, del diametro di 100-150cm; le foglie sono verdi, lunghe 60-90cm e larghe 5-12cm, con striature di un verde più scuro sulla pagina superiore e quasi nere sulla pagina inferiore; il fusto ramificato, alto 120-180cm, sostiene fiori gialli con brattee di colore verde chiaro; le varietà coltivate fioriscono raramente. V. x poelmannii ha foglie verde chiaro, e una grande spiga fiorale con fiori gialli e brattee cremisi dalle punte verde-giallastre. V. splendens ha foglie piegate in fuori, di un verde acceso, con splendide striature trasversali di colore rosso-brunastro e una infiorescenza spiciforme, lunga 30-60cm, composta da fiori gialli e brattee sovrapposte di colore rosso-aranciato. V. zamorensis ha foglie semplici, di colore verde chiaro, una spiga ramificata e un fusto rosso-verdastro; i fiori sono bianchi e le brattee di un rosso vivo con punte gialle.$t$, $j${"luce": "Luminosa, ma non esposta ai raggi diretti del sole (per esempio una finestra rivolta a oriente od occidente)", "acqua": "Terreno sempre umido; versare l'acqua anche nella rosetta in primavera/estate, ma tenerla asciutta in inverno", "terreno": "Non calcareo, ricco di humus: miscela di torba, sfagno, pacciame e concime organico"}$j$::jsonb, ARRAY[$t$tutte le specie di solito vengono acquistate quando il fusto fiorale si è già sviluppato; al termine della fioritura la pianta muore$t$, $t$dopo 3 anni, la pianta può essere avvolta in un sacco di plastica che contenga mele mature (che rilasciano etilene), perché questo procedimento favorisce la fioritura$t$, $t$quando le radici si sono formate sui nuovi germogli, recidere con cautela e trapiantarli in terriccio non calcareo$t$, $t$la fonte non riporta il simbolo di tossicità per questo genere$t$], $j${"irrigazione": {"primavera": "terreno umido, versare acqua anche nella rosetta", "estate": "terreno umido, versare acqua anche nella rosetta, nebulizzare spesso", "autunno": "diradare le innaffiature", "inverno": "diradare, rosetta asciutta, minimo 18°C"}, "concimazione": {"primavera": "una volta al mese (in estate)", "estate": "una volta al mese (in estate)", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Bromeliaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 3, "rinvaso_ogni_mesi": null, "irrigazione_fattore": 0.8}$j$::jsonb, $t$perenne$t$, $t$vriesea$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$),
($t$Zantedeschia$t$, $t$Zantedeschia aethiopica$t$, $t$Araceae$t$, $t$Zantedeschia è un genere originario dell'Africa meridionale e comprende circa 8 specie. Si tratta di piante erbacee con spesse radici tuberose, fusti carnosi, grandi foglie intere, sagittate, di un verde lucente e uno splendido spadice con molti fiorellini, circondato da una grande spata a forma di coppa. Z. aethiopica (sin. Richardia africana), calla, ha foglie di un verde lucido, cordiformi e ondulate, e uno spadice giallo con spata imbutiforme color avorio. Z. elliottiana ha foglie ovali, cordate, a macchie bianche, e un fusto lungo 60cm con una spata dorata lunga circa 10cm e uno spadice giallo. Z. rehmannii, alta 40-60cm, ha foglie più strette, ovali, lanceolate con splendide striature argentate e spata e spadice (lungo 8cm) stretti, di un rosa chiaro o scuro.$t$, $j${"luce": "Luminosa, protetta dalla luce diretta del sole", "acqua": "Terra sempre umida, con nebulizzazioni regolari", "terreno": "Ricco di humus, mescolato con argilla e concime organico"}$j$::jsonb, ARRAY[$t$pianta comunemente nota come calla$t$, $t$il genere Zantedeschia è ben noto per la tossicità di tutte le parti della pianta (contengono ossalato di calcio, irritante se ingerito o a contatto con la pelle): fatto botanico ampiamente documentato, non specificamente segnalato dal libro con il simbolo "!"$t$, $t$dopo la fioritura (settembre/ottobre) le piante hanno bisogno di un periodo di riposo, durante il quale saranno sospese le innaffiature e le foglie appassiranno$t$, $t$conservare il bulbo in luogo asciutto, luminoso e fresco; rinvasare in gennaio e riporre in un locale più caldo, riprendendo le innaffiature e concimando una volta alla settimana$t$, $t$le piante possono crescere in giardino in una zona molto umida; a metà ottobre trasferirle in nuovi vasi e conservarle per tutto l'inverno in un luogo fresco$t$, $t$moltiplicazione per divisione del bulbo e per semina$t$], $j${"irrigazione": {"primavera": "ripresa dopo il riposo, in gennaio; poi terra sempre umida", "estate": "terra sempre umida, con nebulizzazioni regolari", "autunno": "sospese dopo la fioritura, le foglie appassiscono", "inverno": "bulbo a riposo, conservato asciutto in luogo fresco"}, "concimazione": {"primavera": "una volta alla settimana (dopo la ripresa in gennaio)", "estate": "una volta alla settimana", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Araceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": ["gennaio"], "resistenza_gelo": "nessuna", "spaziatura_cm": 40, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 4, "rinvaso_ogni_mesi": 12, "irrigazione_fattore": 0.9}$j$::jsonb, $t$perenne$t$, $t$zantedeschia$t$, ARRAY[$t$Fiori e Piante da Appartamento (collana Fiori & Piante, Edicart/Royal Smeets Offset, 1995) — pagine fotografate da Roberta$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (foto libro lette direttamente)$t$);
